#include <stdio.h>

void printCount(int arr[]) {
    int count = sizeof(arr) / sizeof(arr[0]);
    printf("%d\n", count);
}

int main() {
    int numbers[5] = {1, 2, 3, 4, 5};
    printCount(numbers);
    return 0;
}

correctedCode:
#include <stdio.h>

void printCount(int arr[], int length) {
    printf("%d\n", length);
}

int main() {
    int numbers[5] = {1, 2, 3, 4, 5};
    printCount(numbers, sizeof(numbers) / sizeof(numbers[0]));
    return 0;
}
